import base64
import os
from dataclasses import dataclass
from typing import Tuple

from cryptography.hazmat.primitives.ciphers.aead import AESGCM
import boto3


@dataclass
class EnvelopeCiphertext:
    encrypted_data_key_b64: str
    nonce_b64: str
    ciphertext_b64: str
    kms_key_id: str


class EnvelopeEncryptionError(Exception):
    pass


class AWSKMSEnvelopeEncryption:
    def __init__(self, kms_key_id: str, region_name: str | None = None):
        self.kms_key_id = kms_key_id
        self.kms = boto3.client("kms", region_name=region_name)

    def encrypt(self, plaintext: bytes, aad: bytes | None = None) -> EnvelopeCiphertext:
        if not isinstance(plaintext, (bytes, bytearray)):
            raise TypeError("plaintext must be bytes")
        if aad is not None and not isinstance(aad, (bytes, bytearray)):
            raise TypeError("aad must be bytes or None")

        try:
            resp = self.kms.generate_data_key(KeyId=self.kms_key_id, KeySpec="AES_256")
            plaintext_data_key = resp["Plaintext"]
            encrypted_data_key = resp["CiphertextBlob"]
        except Exception as e:
            raise EnvelopeEncryptionError(f"KMS data key generation failed: {e}") from e

        try:
            aesgcm = AESGCM(plaintext_data_key)
            nonce = os.urandom(12)
            ciphertext = aesgcm.encrypt(nonce, bytes(plaintext), aad)
        finally:
            for i in range(len(plaintext_data_key)):
                try:
                    plaintext_data_key[i] = 0
                except Exception:
                    break

        return EnvelopeCiphertext(
            encrypted_data_key_b64=base64.b64encode(encrypted_data_key).decode("utf-8"),
            nonce_b64=base64.b64encode(nonce).decode("utf-8"),
            ciphertext_b64=base64.b64encode(ciphertext).decode("utf-8"),
            kms_key_id=self.kms_key_id,
        )

    def decrypt(self, envelope: EnvelopeCiphertext, aad: bytes | None = None) -> bytes:
        if aad is not None and not isinstance(aad, (bytes, bytearray)):
            raise TypeError("aad must be bytes or None")

        try:
            encrypted_data_key = base64.b64decode(envelope.encrypted_data_key_b64)
            nonce = base64.b64decode(envelope.nonce_b64)
            ciphertext = base64.b64decode(envelope.ciphertext_b64)
        except Exception as e:
            raise EnvelopeEncryptionError(f"Invalid envelope encoding: {e}") from e

        try:
            resp = self.kms.decrypt(CiphertextBlob=encrypted_data_key, KeyId=envelope.kms_key_id)
            plaintext_data_key = resp["Plaintext"]
        except Exception as e:
            raise EnvelopeEncryptionError(f"KMS data key decryption failed: {e}") from e

        try:
            aesgcm = AESGCM(plaintext_data_key)
            plaintext = aesgcm.decrypt(nonce, ciphertext, aad)
        finally:
            for i in range(len(plaintext_data_key)):
                try:
                    plaintext_data_key[i] = 0
                except Exception:
                    break

        return plaintext


def encrypt_with_aws_kms(plaintext: bytes, kms_key_id: str, aad: bytes | None = None, region_name: str | None = None) -> EnvelopeCiphertext:
    return AWSKMSEnvelopeEncryption(kms_key_id=kms_key_id, region_name=region_name).encrypt(plaintext, aad=aad)


def decrypt_with_aws_kms(envelope: EnvelopeCiphertext, aad: bytes | None = None, region_name: str | None = None) -> bytes:
    return AWSKMSEnvelopeEncryption(kms_key_id=envelope.kms_key_id, region_name=region_name).decrypt(envelope, aad=aad)
